"""Matched-container direct exports of native Kronecker and ordinary low-rank factors."""
import json,pathlib,subprocess,sys,torch
from common import ROOT,PREFIX,write_json,digest,gpu_guard
from math_codec import tensor_bytes
from models import make_paired,Model
from data_audit import latest_data
from training import evaluate

def reload(path,outpath,tokenroot):
    gpu_guard();p=torch.load(path,weights_only=True);model=Model(p['kind']).to('cuda:0');combined={**p['shared'],**p['factors']};model.load_state_dict(combined,strict=True);tokens=torch.load(pathlib.Path(tokenroot)/'test.pt',weights_only=True).to('cuda:0');result=evaluate(model,tokens);result.update(fresh_process=True,original_weights_loaded=False,representation=p['kind']+'_direct_factors',execution='factors materialized by training-model forward, no optimized speed claim');write_json(outpath,result)

def main(out,args):
    selected_path=pathlib.Path(args.checkpoint);selected=json.loads(selected_path.read_text());kind=selected['kind'];assert kind in ['native','lowrank','adamw'];choice=next(c for c in selected['choices'] if c['steps']==selected['selected_steps']);checkpoint_path=pathlib.Path(choice['checkpoint']);record=json.loads((PREFIX/'results'/checkpoint_path.parent.name.removeprefix('training_')/(checkpoint_path.stem+'.json')).read_text());assert record['path']==str(checkpoint_path) and digest(checkpoint_path)==record['sha256'],'selected checkpoint bytes changed';checkpoint=torch.load(checkpoint_path,weights_only=True,map_location='cpu');model=make_paired(kind,selected['seed']);model.load_state_dict(checkpoint['model']);state=model.state_dict();factors={n:v.half() for n,v in state.items() if '.moe.' in n and '.router.' not in n};shared={n:(v.half() if args.codec=='all_fp16' and v.is_floating_point() else v.clone()) for n,v in state.items() if n not in factors};package={'kind':kind,'shared':shared,'factors':factors,'storage':'allFP16 rounded parameter baseline' if args.codec=='all_fp16' else 'FP16 factors/rows, FP32 unaffected parameters; matched complete-bank container for both controls'};artifact=ROOT/'artifacts'/('direct_factor_'+out.name);artifact.mkdir(exist_ok=False);path=artifact/(kind+'_direct.pt')
    with path.open('xb') as f:torch.save(package,f)
    data=latest_data();evpath=out/'fresh_reload.json';subprocess.run([sys.executable,'-B','-c','import sys;from direct_factor_export import reload;reload(*sys.argv[1:])',str(path),str(evpath),data['artifact']],check=True);ev=json.loads(evpath.read_text());weights=4*2*16*256*256;whole=sum(v.numel() for n,v in shared.items() if n!='mask')+weights
    write_json(out/'direct_factor_results.json',{'kind':kind,'variant':'all_fp16' if args.codec=='all_fp16' else 'expert_fp16_shared_fp32','seed':selected['seed'],'selected_steps':selected['selected_steps'],'function_matched':selected['function_matched'],'selected_source':str(selected_path),'source_checkpoint_sha256':record['sha256'],'original_test_nll':selected['baseline']['test']['nll'],'reloaded_test_nll':ev['nll'],'delta_nll':ev['nll']-selected['baseline']['test']['nll'],'expert_tensor_bytes':tensor_bytes(factors),'expert_bpw':8*tensor_bytes(factors)/weights,'whole_model_tensor_bytes':tensor_bytes(package),'whole_model_bpw':8*tensor_bytes(package)/whole,'serialized_bytes':path.stat().st_size,'archive_sha256':digest(path),'archive':str(path),'fresh_process_evaluation':True,'execution':ev['execution'],'learned_expert_scalars':sum(v.numel() for v in factors.values()),'containers_matched':True})
